enum KillTarget {
    Player,
    Mob(usize),
}

/// THE SORT ORDER'S OWN WORD (javap `EntitySelectorParser`'s
/// ORDER_NEAREST/ORDER_FURTHEST/ORDER_RANDOM BiConsumers — the four
/// spellings the `sort=` option's readUnquotedString switch speaks,
/// the unknown word the ERROR_SORT_UNKNOWN verdict answers).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum SelectorSort {
    Nearest,
    Furthest,
    Random,
    Arbitrary,
}

impl SelectorSort {
    /// THE WORD'S OWN PARSE (lambda$bootStrap$25's hashCode switch —
    /// the four words the order enum answers, everything else the
    /// ERROR_SORT_UNKNOWN failure wears).
    fn parse(word: &str) -> Option<Self> {
        match word {
            "nearest" => Some(Self::Nearest),
            "furthest" => Some(Self::Furthest),
            "random" => Some(Self::Random),
            "arbitrary" => Some(Self::Arbitrary),
            _ => None,
        }
    }
}

/// THE DOUBLES RANGE'S OWN PARSE (javap `MinMaxBounds$Bounds
/// .fromReader` — the no-dot word the EXACT form wears (max := min,
/// pc 74-76), the `..` split the bounded sides read, the readNumber
/// walk the empty run the Optional.empty keeps, the BOTH-empty
/// verdict the ERROR_EMPTY answers (pc 78-101), the min>max the
/// ERROR_SWAPPED wears). The bounds the caller the SQUARED distance
/// compares (the matchesSqr law the square the caller folds).
fn parse_selector_distance(value: &str) -> Option<(f64, f64)> {
    let (min_part, max_part) = match value.split_once("..") {
        Some((min_part, max_part)) => (min_part, max_part),
        // THE EXACT FORM (pc 74-76 — the no-dot word the SAME number
        // both sides wears)
        None => (value, value),
    };
    // THE BOTH-EMPTY VERDICT (pc 78-101 — `..` alone the ERROR_EMPTY
    // keeps, the bare empty the canRead head refuses)
    if min_part.is_empty() && max_part.is_empty() {
        return None;
    }
    let min = if min_part.is_empty() {
        f64::NEG_INFINITY
    } else {
        min_part.parse().ok()?
    };
    let max = if max_part.is_empty() {
        f64::INFINITY
    } else {
        max_part.parse().ok()?
    };
    // THE SWAPPED VERDICT (MinMaxBounds.ERROR_SWAPPED — the areSwapped
    // walk the min>max range refuses)
    if min > max {
        return None;
    }
    Some((min, max))
}

/// THE PARSED SELECTOR'S OWN SHAPE (the head + the options the region
/// carries: the `type=` filters the negation flag the `!` prefix
/// wears, the `distance=` range the squared compare answers, the
/// `limit=` the maxResults cap, the `sort=` the order word the
/// sortAndLimit walk applies).
#[derive(Debug, Clone, PartialEq)]
struct ParsedEntitySelector {
    head: SelectorHead,
    types: Vec<(bool, String)>,
    distance: Option<(f64, f64)>,
    limit: Option<usize>,
    sort: Option<SelectorSort>,
}

/// THE ENTITY TYPE'S OWN REGISTRY ID (the mob kind the wire name the
/// from_wire_name walk answers — the reverse the type filter's
/// predicate reads; the ten kinds the enum speaks the total match
/// wears).
fn mob_kind_entity_id(kind: crate::mob::MobKind) -> &'static str {
    match kind {
        crate::mob::MobKind::Zombie => "minecraft:zombie",
        crate::mob::MobKind::Pig => "minecraft:pig",
        crate::mob::MobKind::Cow => "minecraft:cow",
        crate::mob::MobKind::Sheep => "minecraft:sheep",
        crate::mob::MobKind::Chicken => "minecraft:chicken",
        crate::mob::MobKind::Skeleton => "minecraft:skeleton",
        crate::mob::MobKind::Spider => "minecraft:spider",
        crate::mob::MobKind::Wolf => "minecraft:wolf",
        crate::mob::MobKind::Creeper => "minecraft:creeper",
        crate::mob::MobKind::Warden => "minecraft:warden",
    }
}

/// THE ATTACKER'S OWN DISPLAY NAME (vanilla `Entity.getDisplayName()`'s
/// walk — the entity-type lang key the en_us table answers,
/// `entity.minecraft.zombie` = "Zombie"): the killer word the death
/// message's %2$s arg wears, the missing key the getOrDefault law the
/// key ITSELF renders.
fn mob_kind_display_name(kind: crate::mob::MobKind) -> String {
    let key = format!(
        "entity.{}",
        mob_kind_entity_id(kind).replace(':', ".")
    );
    tr(&key).unwrap_or(key.as_str()).to_string()
}

/// THE ENTITY SELECTOR WORD'S OWN PARSE (javap
/// `EntitySelectorParser` — the `@` the readStartingWord verdict
/// keeps, the head letter the five selectors' own words answer, the
/// `[` the options region the readOptions loop consumes to the
/// `]` close). THE OPTIONS the type lane alone carries (the
/// `type=` elements the negation `!` prefix rides — the OTHER
/// registered keys the offline vocabulary the honest absence keeps,
/// the parse failure the brigadier verdict answers). THE ID the
/// registry the resolve keeps: the ten mob ids AND the player the
/// entity types speak, the unknown id the ERROR_INVALID_TYPE
/// verdict wears, the tag `#` form the offline walk never serves.
fn parse_entity_selector_word(word: &str) -> Option<ParsedEntitySelector> {
    let rest = word.strip_prefix('@')?;
    let mut chars = rest.chars();
    let head = match chars.next()? {
        's' => SelectorHead::SelfEntity,
        'p' => SelectorHead::NearestPlayer,
        'a' => SelectorHead::AllPlayers,
        'r' => SelectorHead::RandomPlayer,
        'e' => SelectorHead::AllEntities,
        _ => return None,
    };
    let tail = chars.as_str();
    let (types, distance, limit, sort) = if tail.is_empty() {
        (Vec::new(), None, None, None)
    } else {
        // THE OPTIONS REGION (the `[` open the bracket walk demands —
        // the close the region's own tail wears)
        let interior = tail.strip_prefix('[')?.strip_suffix(']')?;
        let mut types = Vec::new();
        let mut distance: Option<(f64, f64)> = None;
        let mut limit: Option<usize> = None;
        let mut sort: Option<SelectorSort> = None;
        for element in interior.split(',') {
            // THE KEY=VALUE SPLIT (the four registered keys the
            // honored lanes answer — the other registered keys the
            // parse failure the offline vocabulary speaks)
            let (key, value) = element.split_once('=')?;
            match key {
                "type" => {}
                "distance" => {
                    // THE RANGE LANE (the parse_selector_distance walk
                    // the fromReader law keeps)
                    distance = Some(parse_selector_distance(value)?);
                    continue;
                }
                "limit" => {
                    // THE MAXRESULTS LANE (lambda$bootStrap$23 — the
                    // readInt walk the below-1 the
                    // ERROR_LIMIT_TOO_SMALL refuses)
                    limit = Some(value.parse::<usize>().ok().filter(|&n| n >= 1)?);
                    continue;
                }
                "sort" => {
                    // THE ORDER LANE (lambda$bootStrap$25 — the four
                    // words the switch answers, the rest the
                    // ERROR_SORT_UNKNOWN failure wears)
                    sort = Some(SelectorSort::parse(value)?);
                    continue;
                }
                _ => return None,
            }
            // THE NEGATION PREFIX (the `!` the type walk strips — the
            // excluded id the negation set joins)
            let (negated, id) = match value.strip_prefix('!') {
                Some(rest) => (true, rest),
                None => (false, value),
            };
            // THE ID RUN (the [a-z0-9_.-] charset the identifier walk
            // keeps, the `:` the namespace separator rides, the
            // minecraft: prefix the strip answers, the tag `#` the
            // offline walk never serves)
            if id.starts_with('#')
                || !id
                    .chars()
                    .all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || matches!(c, '_' | '.' | '-' | ':'))
            {
                return None;
            }
            let path = id.strip_prefix("minecraft:").unwrap_or(id);
            // THE REGISTRY RESOLVE (the ten mob ids AND the player the
            // entity registry speaks — the unknown id the
            // ERROR_INVALID_TYPE verdict keeps)
            if path != "player" && parse_kind_path(path).is_none() {
                return None;
            }
            if path == "player" {
                types.push((negated, "player".to_string()));
            } else {
                types.push((negated, format!("minecraft:{path}")));
            }
        }
        (types, distance, limit, sort)
    };
    Some(ParsedEntitySelector {
        head,
        types,
        distance,
        limit,
        sort,
    })
}

/// THE TYPE PATH'S OWN KIND RESOLVE (the parse's registry walk — the
/// bare path the MobKind the from_wire_name law answers, the unknown
/// path the honest None keeps).
fn parse_kind_path(path: &str) -> Option<crate::mob::MobKind> {
    Some(match path {
        "zombie" => crate::mob::MobKind::Zombie,
        "pig" => crate::mob::MobKind::Pig,
        "cow" => crate::mob::MobKind::Cow,
        "sheep" => crate::mob::MobKind::Sheep,
        "chicken" => crate::mob::MobKind::Chicken,
        "skeleton" => crate::mob::MobKind::Skeleton,
        "spider" => crate::mob::MobKind::Spider,
        "wolf" => crate::mob::MobKind::Wolf,
        "creeper" => crate::mob::MobKind::Creeper,
        "warden" => crate::mob::MobKind::Warden,
        _ => return None,
    })
}

