                            let a = pig.ridden_speed();
                            let rad = pig.yaw as f64 * std::f64::consts::PI / 180.0;
                            let (s, c) = rad.sin_cos();
                            pig.vx += (0.0f64 * c - 1.0f64 * s) * a;
                            pig.vz += (1.0f64 * c + 0.0f64 * s) * a;
