                    // keeps, the fire lanes the hurt/death rows speak,
                    // the extinguish the fizz plays — the LOOT the
                    // death walk rolls AT the pig (the entity's own
                    // stream the rolls ride, the caller's health
                    // crossing contract keeps)
                    let mut ride_ambient = false;
                    let mut ride_fire_hurt = false;
                    let mut ride_fire_death = false;
                    let mut ride_fizz = None::<f32>;
                    let mut ride_loot: Vec<(i32, i32)> = Vec::new();
                    let mut ride_words = None::<[&'static str; 3]>;
                    let mut ride_pitch = 1.0f32;
                    let mut ride_pose = (0.0f64, 0.0f64, 0.0f64);
                    if let Some(w) = world {
                        if let Some(pig) = self.mobs.iter_mut().find(|m| m.id == vid) {
                            ride_words = Some([
                                // THE STATELESS AMBIENT BANK (the
                                // pre-tick order the vehicle lane's
                                // own contract keeps — the pig the
                                // mount admits, no state the word
                                // reads; the WOLF'S four-arm selection
                                // the vehicle never carries — no wolf
                                // mount the game speaks, the post-gate
                                // lane's own roll the ambient_voice_
                                // event method wears)
                                pig.voice_event(crate::mob::VoiceSlot::Ambient),
                                pig.voice_event(crate::mob::VoiceSlot::Hurt),
                                pig.voice_event(crate::mob::VoiceSlot::Death),
                            ]);
                            let ev = pig.tick(w, player_view.as_ref(), day_time);
                            step_ev = ev.step;
                            step_at = Some((pig.x, pig.y, pig.z));
                            ride_ambient = ev.ambient;
                            ride_fire_hurt = ev.fire_hurt;
                            ride_fire_death = ev.fire_death;
                            ride_fizz = ev.extinguished;
                            ride_pitch = pig.voice_pitch();
                            ride_pose = (pig.x, pig.y, pig.z);
                            if ride_fire_death {
                                ride_loot = pig.death_loot(false);
                            }
                        }
                    }
                    if let (true, Some((px, py, pz))) = (step_ev, step_at) {
                        // THE FOOTSTEP'S OWN VOICE (the kind's step_voice
                        // the block law rides — the same play_voice_at
                        // the mob loop's own steps speak)
                        let under = crate::world::NAME_OF[world
                            .map(|w| {
                                w.get(
                                    px.floor() as i32,
                                    (py - 0.2).floor() as i32,
                                    pz.floor() as i32,
                                )
                            })
                            .unwrap_or(crate::world::AIR) as usize];
                        if let Some(pig) = self.mobs.iter().find(|m| m.id == vid) {
                            if let Some((event, volume, pitch)) =
                                pig.step_voice(Some(under))
                            {
                                let ear = Some((b.x, b.y + b.eye_height(), b.z));
                                self.sounds.play_voice_at_pan(
                                    self.frame,
                                    event,
                                    volume,
                                    pitch,
                                    ear_distance(ear, pig.x, pig.y, pig.z),
                                    // the body's own yaw the vanilla
                                    // degrees the pan law speaks (the
                                    // body's word the +180° fold the
                                    // camera conversion wears)
                                    ear_pan(ear, b.yaw, pig.x, pig.y, pig.z),
                                );
                            }
                        }
                    }
                    // THE RIDE'S OWN VOICES (the loop's own consumption
                    // the mirrored walk speaks — the KIND'S OWN ROW
                    // each event the voice table keeps, the distance
                    // law the rider's own ear folds, the stereo tail
                    // the body's own yaw the pan law speaks)
                    let ear = Some((b.x, b.y + b.eye_height(), b.z));
