                    b.y = fy;
                    b.z = fz;
                    b.vx = 0.0;
                    b.vy = 0.0;
                    b.vz = 0.0;
                    b.on_ground = false;
                    b.horizontal_collision = false;
                    b.forward = 0.0;
                    b.left = 0.0;
                    b.jumping = false;
