    fn wire_zombie(id: i32, x: f64, y: f64, z: f64) -> crate::world_view::WireMob {
        crate::world_view::WireMob {
            id,
            x,
            y,
            z,
            yaw: 90.0,
            pitch: 5.0,
            head_yaw: 60.0,
            health: None,
            hurt_time: 0,
            on_fire: false,
            crouching: false,
            climbing: false,
            wool_byte: 0,
            baby: false,
            chicken_variant: None,
            pig_variant: None,
            cow_variant: None,
chicken_sound_variant: None,
pig_sound_variant: None,
cow_sound_variant: None,
            held_weapon: None,
            held_offhand: None,
            armor: [None; 4],
            custom_name: None,
            name_visible: false,
            score_text: None,
            type_name: "minecraft:zombie".to_string(),
        }
    }

