            w.set(c, surface + 1, c, crate::world::STONE); // the occupied above
            // the trench the side ray's own layer clears (the ray's
            // path the camera-to-face walk keeps solid-free)
            for dz in -3..0 {
                w.set(c, surface, c + dz, crate::world::AIR);
            }
